// Browser-local import/export. Input files are data; none of their expressions execute here.
let originalText='',profileMessage='',importQuery='';
function message(title,text){let d=document.getElementById('messageDialog');document.getElementById('messageTitle').textContent=title;document.getElementById('messageBody').textContent=text;if(d?.showModal)d.showModal();else alert(title+'\n'+text)}
function cleanRule(rule){if(!rule||typeof rule!=='object'||!Array.isArray(rule.requirements))throw Error('Invalid imported rule.');const q={name:String(rule.name??''),expression:String(rule.expression??''),priority:rule.priority??0,action:rule.action,quantity:rule.quantity??null,requirements:rule.requirements.map(q=>{if(!Number.isSafeInteger(q.type)||typeof q.data!=='string')throw Error('Invalid requirement data.');return {type:q.type,data:q.data}})};return UTL.parse(UTL.write({rules:[q],extras:[]})).rules[0]}
function cleanExtra(b){if(!b||typeof b.name!=='string'||typeof b.data!=='string'||/[\r\n]/.test(b.name))throw Error('Invalid UTL extension.');return {name:b.name,data:b.data}}
function initIO(){state.materials=state.materials.filter(m=>UTLDATA.materialIds[m.name]);if(!Array.isArray(state.serverItems))state.serverItems=structuredClone(UTLDATA.server);if(!Array.isArray(state.importedRules))state.importedRules=[];if(!Array.isArray(state.importedExtras))state.importedExtras=[];for(const e of state.importedRules)if(/^\(CL\)/.test(e.rule.name))e.group='Cloaks';if(!state.profileName||state.profileName==='NoobLoot')state.profileName='BroLoot';if(!state.sourceFile)state.sourceFile='New DreamWeave profile';}
function snapshot(){let s=structuredClone(state);delete s.originalText;return s}
function fileName(name,ext){return (String(name||'BroLoot').replace(/\.(utl|json)$/i,'').replace(/[^\w .-]/g,'_').slice(0,100)||'BroLoot')+ext}
function download(text,name,type){if(globalThis.brolootDesktop)return globalThis.brolootDesktop.saveFile(text,name);const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);return {status:'requested',name}}
async function downloadSettings(){try{const result=await download(JSON.stringify({format:'BroLoot settings',version:6,...snapshot()},null,2),fileName(state.profileName,'-settings.json'),'application/json');reportSave(result,'Settings')}catch(e){message('Could not save settings',e.message)}}
function validateSnapshot(s){if(!s||typeof s!=='object')throw Error('Invalid BroLoot settings.');let out={...snapshot()};
 for(const cat of equipmentCategories){if(cat==='Cloaks'&&!s.Cloaks)s={...s,Cloaks:[{...fresh('Level 5 cloak','Cloaks'),enabled:false}]};if(cat==='Trinkets'&&!s.Trinkets)s={...s,Trinkets:structuredClone(s.Jewelry).map(t=>({...t,name:t.name+' · legacy trinkets'}))};if(!Array.isArray(s[cat])||!s[cat].length||s[cat].length>2000)throw Error('Invalid '+cat+' targets.');out[cat]=s[cat].map(t=>{if(!t||!Array.isArray(t.spells)||!Array.isArray(t.tiers)||!Array.isArray(t.sets)||typeof t.enabled!=='boolean'||typeof t.name!=='string'||/[\r\n]/.test(t.name)||t.name.length>500)throw Error('Invalid equipment target.');let result={...UTL.ratingDefaults(t),spells:t.spells.filter(x=>allowedSpell(cat,x)),tiers:t.tiers.filter(x=>tiers.includes(x)),sets:t.sets.filter(x=>sets.includes(x))};for(const k of [...Object.keys(UTL.RATINGS),'count'])if(!Number.isInteger(result[k])||result[k]<0||result[k]>100)throw Error('Invalid target '+k+'.');if(cat==='Cloaks'){result.cloakLevel=t.cloakLevel??0;result.cloakSet=t.cloakSet??0;result.cloakProc=t.cloakProc||'any';if(t.cloakNamePattern!=null&&(typeof t.cloakNamePattern!=='string'||t.cloakNamePattern.length>500))throw Error('Invalid imported cloak name filter.');UTL.cloakRequirements(result)}return result})}
 if(!DATA.profiles[s.weaponPreset]||!Array.isArray(s.weapons)||s.weapons.length>2000)throw Error('Invalid weapon settings.');out.weaponPreset=s.weaponPreset;out.weapons=s.weapons.map(w=>{if(!Number.isFinite(+w.minimum)||+w.minimum<0||typeof w.enabled!=='boolean')throw Error('Invalid weapon threshold.');let source=DATA.profiles[s.weaponPreset].find(x=>x.source===w.source);if(!source&&!w.template)throw Error('Unknown weapon template.');let result={...source,...w,minimum:+w.minimum};if(w.template)result.template=cleanRule(w.template);return result});
 if(!Array.isArray(s.materials))throw Error('Invalid salvage settings.');out.materials=structuredClone(DATA.materials).filter(m=>UTLDATA.materialIds[m.name]).map(m=>{let given=s.materials.find(x=>x.name===m.name);if(!given)return m;if(typeof given.enabled!=='boolean'||!Number.isInteger(given.minimum)||!Number.isInteger(given.maximum)||given.minimum<1||given.maximum>10||given.minimum>given.maximum||typeof given.combine!=='string'||!validRanges(given.combine))throw Error('Invalid salvage range for '+m.name+'.');return {...m,...given}});
 if(!Number.isInteger(s.reserve)||s.reserve<0||s.reserve>1000||typeof s.custom!=='boolean')throw Error('Invalid global settings.');out.reserve=s.reserve;out.custom=s.custom;out.quantity=s.quantity??0;
 out.serverItems=(s.serverItems||UTLDATA.server).map(e=>{if(!Number.isInteger(e.quantity)||e.quantity<0||e.quantity>2147483647||typeof e.enabled!=='boolean')throw Error('Invalid server-item quantity.');return {group:String(e.group||'Other'),order:Number.isInteger(e.order)?e.order:null,enabled:e.enabled,quantity:e.quantity,rule:cleanRule(e.rule)}});
 out.importedRules=(s.importedRules||[]).map(e=>({enabled:!!e.enabled,order:Number.isInteger(e.order)?e.order:null,group:String(e.group||'Other'),rule:cleanRule(e.rule)}));out.importedExtras=(s.importedExtras||[]).filter(e=>e.name!=='NoobLootSettings').map(cleanExtra);out.profileName=String(s.profileName||'BroLoot').replace(/[\r\n]/g,' ').slice(0,100);out.sourceFile=String(s.sourceFile||'BroLoot settings').slice(0,200);return out}
function importGroup(r){if(/^~~/.test(r.name))return 'Editor metadata';if(/^\*/.test(r.name)&&UTL.disabled(r))return 'Section labels';if(r.action===2)return 'Salvage';if(/^\((H|L|F|2H|M|W)\)/.test(r.name))return 'Weapons';if(/^\(CL\)/.test(r.name))return 'Cloaks';if(/^\(A\)/.test(r.name))return 'Armor';if(/^\(C\)/.test(r.name))return 'Underclothes';if(/^\(J\)/.test(r.name))return 'Jewelry';if(/^Trinkets:/.test(r.name))return 'Trinkets';return 'Other loot'}
function importedState(doc,name){let out=snapshot();out.profileName=name.replace(/\.utl$/i,'');out.sourceFile=name;out.importedRules=[];out.importedExtras=doc.extras.map(cleanExtra);out.serverItems=[];out.custom=true;
 for(const cat of equipmentCategories)out[cat]=out[cat].map(t=>({...t,enabled:false}));out.weapons=out.weapons.map(w=>({...w,enabled:false}));out.materials=out.materials.map(m=>({...m,enabled:false}));
 let group='Other';for(const [order,r] of doc.rules.entries()){if(/^\*\* [^*]/.test(r.name))group=r.name.replace(/\*/g,'').trim();if(r.name.startsWith('(DW)')||r.name==='DreamWeave rare')out.serverItems.push({group,order,enabled:!UTL.disabled(r),quantity:r.action===10?r.quantity:0,rule:cleanRule(r)});else out.importedRules.push({order,enabled:!UTL.disabled(r),group:importGroup(r),rule:r})}
 if(!out.serverItems.length)out.custom=false;let block=doc.extras.find(b=>b.name==='SalvageCombine');if(block){let ls=block.data.trimEnd().split(/\r?\n/),n=+ls[2],i=3,map={};for(let j=0;j<n;j++)map[ls[i++]]=ls[i++];out.materials=out.materials.map(m=>({...m,combine:map[UTLDATA.materialIds[m.name]]||ls[1]}))}return out}
async function importFile(file){if(!file)return;try{if(file.size>16*1024*1024)throw Error('Choose a file smaller than 16 MB.');const text=await file.text();let next,doc=null;if(/\.json$/i.test(file.name)){next=validateSnapshot(JSON.parse(text));}else{doc=UTL.parse(text);let own=UTL.readSettings(doc);next=own?validateSnapshot(own):importedState(doc,file.name)}if(!confirm('Open '+file.name+' and replace the current editor settings? Save settings first if you need a backup.'))return;state=next;originalText=doc?text:'';initIO();profileMessage=doc?UTL.readSettings(doc)?'BroLoot settings restored from UTL.':'Imported rules retained in their original order. Existing equipment and salvage rules are under Imported rules; new targets start disabled.':'BroLoot settings restored.';persist();tab='Profile';selected=0;render()}catch(e){message('Could not open profile',e.message)}}
function buildProfile(){let doc=UTL.compile(snapshot(),DATA,UTLDATA),text=UTL.write(doc);UTL.parse(text);return {doc,text}}
function reportSave(result,kind){if(result.status==='cancelled'){profileMessage='Save cancelled. No file was written.'}else if(result.status==='saved'){profileMessage=kind+' saved to '+result.detail}else{profileMessage=kind+' download requested. Check your browser downloads.'}if(tab==='Profile')render();else message(result.status==='saved'?'File saved':result.status==='cancelled'?'Save cancelled':'Download requested',profileMessage)}
async function exportUTL(){try{for(const m of state.materials)if(!validRanges(m.combine))throw Error('Fix the combination ranges for '+m.name+'.');let built=buildProfile(),result=await download(built.text,fileName(state.profileName,'.utl'),'application/octet-stream');reportSave(result,'UTL profile')}catch(e){message('Export needs attention',e.message)}}
async function downloadOriginal(){if(originalText)try{reportSave(await download(originalText,fileName(state.sourceFile,'-original.utl'),'application/octet-stream'),'Original profile')}catch(e){message('Could not save original',e.message)}}
function profilePanel(){let counts={};for(const cat of equipmentCategories)counts[cat]=state[cat].filter(t=>t.enabled).length;let imported=state.importedRules.filter(e=>e.enabled).length;return `${globalThis.brolootDesktop?'':'<div class="card"><h3>BroLoot for Windows</h3><p>Run the editor locally. No sign-in, account, or website access required.</p><a class="download-app" href="downloads/BroLoot-Windows-x64.zip" download="BroLoot-Windows-x64.zip">Download Windows app (.zip)</a><p class="muted">Extract the entire ZIP, then run BroLoot.exe. Send the ZIP directly to your allegiance mates.</p></div>'}<div class="card"><h3>Your profile</h3><p class="muted">Edits save automatically on this PC. Save settings is an optional backup. Export UTL writes the loot profile used by the game.</p>${profileMessage?`<div class="status">${esc(profileMessage)}</div>`:''}<label class="field"><span>Profile name</span><input value="${esc(state.profileName)}" onchange="state.profileName=this.value.replace(/[\\r\\n]/g,' ');persist()"></label><p class="muted">${esc(state.sourceFile)}</p><div class="toolbar"><button class="primary" onclick="exportUTL()">Export .utl</button><button onclick="document.getElementById('importFile').click()">Open .utl or settings</button><button onclick="downloadSettings()">Save settings</button>${originalText?'<button onclick="downloadOriginal()">Download unchanged original</button>':''}<button onclick="newProfile()">New profile</button></div></div><div class="layout"><div class="card"><h3>Enabled targets</h3>${Object.entries(counts).map(([k,n])=>`<p>${k}: <strong>${n}</strong></p>`).join('')}<p>Weapon thresholds: <strong>${state.weapons.filter(w=>w.enabled).length}</strong></p><p>Salvage materials: <strong>${state.materials.filter(m=>m.enabled).length}</strong></p><p>DreamWeave items: <strong>${state.custom?state.serverItems.filter(e=>e.enabled).length:0}</strong></p></div><div class="card"><h3>What your export includes</h3><p>All enabled targets, selected DreamWeave rules, salvage combination settings, and ${imported} enabled imported rules.</p><p>Selected cantrips are minimum requirements. Extra cantrips never reject an item. Selected ratings are alternatives; higher rolls qualify too.</p><p>All looting rules require more than ${state.reserve} free main-pack spaces before looting. Stricter pack-space conditions in imported rules remain intact.</p><p class="muted">Exported profiles include your editor settings, so you can open them again in BroLoot.</p>${state.importedRules.length?'<button onclick="tab=\'Imported\';render()">Review imported rules</button>':''}</div></div>`}
function serverPanel(){let enabled=state.serverItems.filter(e=>e.enabled).length;return `<div class="card"><h3>DreamWeave custom items</h3><label><input type="checkbox" ${state.custom?'checked':''} onchange="state.custom=this.checked;persist();render()"> Retain selected DreamWeave items</label><p class="muted">Keep all is the default. Enter a quantity to keep up to that amount. The pack-space reserve applies to every item.</p><div class="toolbar"><button onclick="serverAll(true)">Enable all</button><button onclick="serverAll(false)">Disable all</button><label>Keep quantity for all <input aria-label="Keep quantity for all server items" id="serverBulk" type="number" min="0" value="${state.quantity}"></label><button onclick="serverQuantity()">Apply quantity</button></div><p>${enabled} of ${state.serverItems.length} items selected · 0 means Keep all</p>${[...new Set(state.serverItems.map(e=>e.group))].map(g=>`<details class="spellgroup" open><summary>${esc(g)}</summary>${state.serverItems.map((e,i)=>e.group!==g?'':`<div class="checkrow"><input aria-label="Enable ${esc(e.rule.name)}" type="checkbox" ${e.enabled?'checked':''} onchange="serverToggle(${i},this.checked)"><span>${esc(e.rule.name.replace(/^\(DW\) /,''))}</span><label>Keep <input aria-label="Keep quantity for ${esc(e.rule.name)}" type="number" min="0" max="2147483647" value="${e.quantity}" onchange="this.value=number(this.value,0,2147483647);state.serverItems[${i}].quantity=+this.value;persist()"></label></div>`).join('')}</details>`).join('')}</div>`}
function serverToggle(i,on){state.serverItems[i].enabled=on;persist();render()}
function serverAll(on){state.serverItems.forEach(e=>e.enabled=on);persist();render()}
function serverQuantity(){let n=Number(document.getElementById('serverBulk').value);if(!Number.isInteger(n)||n<0||n>2147483647){message('Invalid quantity','Use a whole number of zero or greater.');return}state.quantity=n;state.serverItems.forEach(e=>e.quantity=n);persist();render()}
function importedPanel(){if(!state.importedRules.length)return '<div class="card"><h3>No imported rules</h3><p>Open an existing UTL to retain its rules alongside your BroLoot targets.</p></div>';let counts={};state.importedRules.forEach(e=>counts[e.group]=(counts[e.group]||0)+1);return `<div class="imported-summary">Imported rules can keep items beyond your new targets. They remain in their original order. Disable an old rule or category when replacing it with BroLoot controls.</div><div class="card"><div class="toolbar"><input aria-label="Search imported rules" value="${esc(importQuery)}" placeholder="Search imported rules" oninput="filterImported(this.value)"><button onclick="useSalvageControls()">Move supported salvage into controls</button><button onclick="useCloakControls()">Move supported cloaks into controls</button></div>${Object.entries(counts).map(([g,n])=>`<details class="spellgroup" open><summary>${esc(g)} <span class="count">${n} rules</span></summary><div class="toolbar"><button data-group="${esc(g)}" onclick="importedGroup(this.dataset.group,true)">Enable category</button><button data-group="${esc(g)}" onclick="importedGroup(this.dataset.group,false)">Disable category</button></div>${state.importedRules.map((e,i)=>e.group!==g?'':`<div class="checkrow" data-imported="${esc(e.rule.name.toLowerCase())}"><input aria-label="Enable ${esc(e.rule.name)}" type="checkbox" ${e.enabled?'checked':''} ${UTL.disabled(e.rule)?'disabled':''} onchange="state.importedRules[${i}].enabled=this.checked;persist()"><span>${esc(e.rule.name)}</span><span class="badge" style="flex:0">${({1:'Keep',2:'Salvage',3:'Sell',4:'Read',10:'Keep '+e.rule.quantity})[e.rule.action]||'Other'}${UTL.disabled(e.rule)?' · Originally disabled':''}</span></div>`).join('')}</details>`).join('')}</div>`}
function filterImported(q){importQuery=q;document.querySelectorAll('[data-imported]').forEach(n=>n.hidden=!n.dataset.imported.includes(q.toLowerCase()))}
function importedGroup(g,on){state.importedRules.filter(e=>e.group===g&&!UTL.disabled(e.rule)).forEach(e=>e.enabled=on);persist();render()}
function useSalvageControls(){let supported=[];for(let i=0;i<state.importedRules.length;i++){let e=state.importedRules[i],r=e.rule;if(r.action!==2)continue;let material=r.requirements.find(q=>q.type===12&&UTL.parts(q)[1]==='131');if(!material)continue;let name=Object.keys(UTLDATA.materialIds).find(n=>UTLDATA.materialIds[n]===+UTL.parts(material)[0]);if(!name||r.expression)continue;let min=1,max=10,packMinimum=0,ok=true;for(const q of r.requirements){let p=UTL.parts(q);if(q.type===1001){packMinimum=Math.max(packMinimum,+p[0]);continue}if(q===material||q.type===9999)continue;if(q.type===3&&p[1]==='105')min=Math.max(min,+p[0]);else if(q.type===2&&p[1]==='105')max=Math.min(max,+p[0]);else ok=false}if(ok&&min>=1&&max<=10&&min<=max)supported.push({i,name,min,max,packMinimum,enabled:e.enabled&&!UTL.disabled(r)})}
 // Multiple rules for the same material may express disjoint ranges; keep them opaque.
 supported=supported.filter(x=>supported.filter(y=>y.name===x.name).length===1);if(!supported.length){message('Nothing to move','These salvage rules have additional conditions. They will remain intact under Imported rules.');return}if(!confirm('Move '+supported.length+' material rules into the Salvage controls? Their original entries will be disabled to avoid duplicate behavior. Rules with other conditions will remain active.'))return;
 for(const x of supported){let m=state.materials.find(m=>m.name===x.name);Object.assign(m,{enabled:x.enabled,minimum:x.min,maximum:x.max,packMinimum:x.packMinimum});state.importedRules[x.i].enabled=false}persist();tab='Salvage';render()}
function newProfile(){if(!confirm('Start a new profile? Save settings first to keep your current work.'))return;state={Armor:[{...fresh('Adept / Defender · attributes'),sets:['Adept','Defender'],cdr:2}],Underclothes:[fresh('Legendary attributes · D3','Underclothes')],Jewelry:[{...fresh('Legendary wards & magic','Jewelry'),spells:[...groups.Wards,'War Magic Aptitude','Void Magic Aptitude']}],Trinkets:[{...fresh('Health or healing','Trinkets'),enabled:false}],Cloaks:[{...fresh('Level 5 cloak','Cloaks'),enabled:false}],materials:structuredClone(DATA.materials),reserve:5,custom:true,quantity:0,weaponPreset:'LegendaryPlus',weapons:structuredClone(DATA.profiles.LegendaryPlus)};originalText='';profileMessage='New DreamWeave profile. Custom items start at Keep all.';initIO();persist();tab='Profile';selected=0;render()}
function cloakSummary(t){const set=Object.keys(UTL.CLOAKS.sets).find(k=>UTL.CLOAKS.sets[k]===Number(t.cloakSet)),proc=UTL.CLOAKS.procs[t.cloakProc||'any'];return ` (${set||'any set'}; ${proc?.label||'any proc'}${t.cloakLevel?'; level potential ≥ '+t.cloakLevel:''})`}
function cloakControls(t){const legacy=state.importedRules.filter(e=>e.enabled&&e.group==='Cloaks').length;return `<div class="ratings"><h3>Cloak requirements</h3><div class="field"><span>Cloak set</span><select aria-label="Cloak set" onchange="update('cloakSet',+this.value)"><option value="0" ${!t.cloakSet?'selected':''}>Any set</option>${Object.entries(UTL.CLOAKS.sets).sort((a,b)=>a[0].localeCompare(b[0])).map(([name,id])=>`<option value="${id}" ${t.cloakSet===id?'selected':''}>${esc(name)}</option>`).join('')}</select></div><div class="field"><span>Cloak proc</span><select aria-label="Cloak proc" onchange="update('cloakProc',this.value)">${Object.entries(UTL.CLOAKS.procs).map(([key,p])=>`<option value="${key}" ${(t.cloakProc||'any')===key?'selected':''}>${esc(p.label)}</option>`).join('')}</select></div><div class="field"><span>Minimum level potential</span><select aria-label="Minimum cloak level potential" onchange="update('cloakLevel',+this.value)">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${(t.cloakLevel||0)===n?'selected':''}>${n?'Level '+n+' or higher':'Any level'}</option>`).join('')}</select><p class="muted">This is the level the cloak can reach, not its current trained level.</p></div>${t.cloakNamePattern?`<p class="muted">Imported name filter: ${esc(t.cloakNamePattern)} <button onclick="update('cloakNamePattern','');render()">Use all cloak names</button></p>`:''}</div>${legacy?`<div class="imported-summary">${legacy} enabled imported cloak rule${legacy===1?' remains':'s remain'} active and may keep cloaks outside this target. <button onclick="useCloakControls()">Move supported rules into cloak controls</button></div>`:''}`}
function decodeCloakRule(e){const r=e.rule;if(!e.enabled||r.action!==1||r.expression||UTL.disabled(r))return null;let t={...fresh(r.name.replace(/^\(CL\) /,''),'Cloaks'),cloakLevel:0,enabled:true},identified=false,procType=null,procPattern=null;
 for(const q of r.requirements){let p=UTL.parts(q),value=+p[0],key=+p[1];if(q.type===7&&value===3){continue}if(q.type===1&&p[0]==='Cloak$'&&key===1){t.cloakNamePattern=p[0];identified=true;continue}if(q.type===11&&value===0x08000000&&key===218103822){identified=true;continue}if(q.type===3&&key===218103849&&value>=27700&&value<=27704){t.cloakLevel=Math.max(t.cloakLevel,value-27699);continue}if(q.type===3&&key===319&&value>=1&&value<=5){t.cloakLevel=Math.max(t.cloakLevel,value);continue}if(q.type===12&&key===265&&Object.values(UTL.CLOAKS.sets).includes(value)){if(t.cloakSet&&t.cloakSet!==value)return null;t.cloakSet=value;continue}if(q.type===12&&key===352&&[1,2].includes(value)){if(procType!==null&&procType!==value)return null;procType=value;continue}if(q.type===9&&p[1]===''&&p[2]==='1'){if(procPattern)return null;procPattern=p[0];continue}if(q.type===3&&Object.values(UTL.RATINGS).some(x=>x.property===key)&&Number.isInteger(value)&&value>0&&value<=100){let k=Object.keys(UTL.RATINGS).find(k=>UTL.RATINGS[k].property===key);t[k]=Math.max(t[k],value);continue}if(q.type===1001&&Number.isInteger(value)&&value>=0){t.packMinimum=Math.max(t.packMinimum||0,value);continue}if(q.type===9999&&p[0]==='false')continue;return null}
 if(!identified||!r.requirements.some(q=>q.type===7&&UTL.parts(q)[0]==='3'))return null;if(procType===2){if(procPattern)return null;t.cloakProc='damageReduction'}else if(procPattern){let found=Object.entries(UTL.CLOAKS.procs).find(([key,p])=>{if(!p.names)return false;let q=UTL.cloakRequirements({...t,cloakProc:key}).find(q=>q.type===9);return UTL.parts(q)[0]===procPattern});if(!found)return null;t.cloakProc=found[0]}else if(procType===1)t.cloakProc='anySpell';return t}
function useCloakControls(){const supported=[];state.importedRules.forEach((e,i)=>{if(e.group!=='Cloaks')return;let t=decodeCloakRule(e);if(t)supported.push({i,t})});if(!supported.length){message('No supported cloak rules to move','Rules with extra conditions remain under Imported rules. You can create a cloak target and disable the old rule when you are ready.');return}if(!confirm('Move '+supported.length+' cloak rule(s) into the Cloaks controls? Their original entries will be disabled to prevent duplicate behavior.'))return;for(const {i,t} of supported){state.Cloaks.push(t);state.importedRules[i].enabled=false}selected=state.Cloaks.length-1;tab='Cloaks';persist();render()}
